/* ==========================================================================
   Touris 知途 · 预算数据（景点门票档位 + 住宿价位区间）

   ★ 为什么是**档位**而不是精确票价

   门票和住宿价随时在变（淡旺季、免费日、临时调价、园中园另计），而这个产品的
   卖点是「可溯源、可核验」——写一个精确到元的数字，到了出行当天反而变成错的，
   等于自己拆自己的台。所以这里只定档位：够用来判断「这个方案超没超预算」，
   又不假装自己是一份实时报价。界面上统一提示「以官方当日票价为准」。

   ★ 用什么标定档位（不是拍脑袋）

   1. 各城市 spots 里已有的 `免费` / `免费区大` 标签 —— 这类直接进 free；
   2. 门票制的**性质**：市立博物馆与公园常年免费，寺观与古迹多为小额门票，
      主题乐园 / 观景台 / 索道温泉是价格高地；
   3. 无法确证的**宁可往低档放**——高估预算会让用户以为「这趟很贵」而放弃，
      比低估更伤。同理，拿不准的一律不标 high。

   ★ 档位口径（单次门票，不含园中园、讲解与演出票）

     free   免费       公园、街区、广场、多数市立博物馆
     low    人均 ≤50
     mid    人均 50–100
     high   人均 >100   主题乐园、观景台、索道温泉

   ★ 维护约定

   SPOT_TIER 只列**不免费**的景点；**没列到的一律按 free 处理**。
   这跟各城市 spots 的标签是一致的：标了「免费」的 126 个点全落在默认里。
   新增景点时，只有要收门票的才需要往这里加一行。
   ========================================================================== */
(function(){

  const TIER = {
    free: { id:'free', label:'免费',    lo:0,   hi:0,   mid:0  },
    low:  { id:'low',  label:'≤50',     lo:20,  hi:50,  mid:35 },
    mid:  { id:'mid',  label:'50–100',  lo:50,  hi:100, mid:75 },
    high: { id:'high', label:'100+',    lo:100, hi:220, mid:150 }
  };

  /* 景点门票档位。键是 CITY_DATA 里的景点名，必须逐字一致。 */
  const SPOT_TIER = {
    '北京': {
      '故宫博物院':'mid',        // 旺季 60 / 淡季 40
      '景山公园':'low',          // 2
      '天坛公园':'low',          // 旺季 15，联票 34
      '颐和园':'low',            // 旺季 30，联票 60
      '圆明园':'low',            // 10
      '慕田峪长城':'mid',        // 45 + 往返缆车
      '雍和宫':'low',            // 25
      '国子监':'low',            // 30
      '北海公园':'low',          // 10
      '鼓楼':'low',              // 20
      '恭王府':'low',            // 40
      '国家大剧院':'low',        // 参观票 40
      '香山公园':'low',          // 10
      '国家植物园':'low',        // 10
      '卢沟桥':'low',            // 20
      '白塔寺':'low',            // 20
      '法源寺':'low',            // 5
      '湖广会馆':'low',          // 30
      '红砖美术馆':'high',       // 130
      '正乙祠':'mid'             // 以戏票为主
    },
    '上海': {
      '城隍庙':'low',            // 10
      '上海中心':'high',         // 118–180 观光层
      '静安寺':'low',            // 50
      '龙华寺':'low',            // 10
      '世纪公园':'low',          // 10
      '上海科技馆':'low',        // 45
      '西岸美术馆':'mid',        // 特展 60–100
      '龙美术馆':'mid',          // 100
      '上海动物园':'low',        // 40
      '大世界':'high'            // 120 起（含演出）
    },
    '威海': {
      '刘公岛':'high',           // 138，含往返船票
      '中国甲午战争博物院':'low', // 含在刘公岛票内
      '定远舰景区':'mid',        // 60
      '成山头':'mid',            // 旺季 148
      '海驴岛':'mid',            // 100，含船票
      '鸡鸣岛':'mid',            // 88，含船票
      '仙姑顶':'mid',            // 80
      '神雕山野生动物园':'high', // 150
      '赤山景区':'high',         // 120
      '汤泊温泉':'high',         // 198 起
      '摩天岭索道':'mid',        // 100
      '华夏城':'high'            // 98–160
    },
    '杭州': {
      '雷峰塔':'low',            // 40
      '灵隐寺':'mid',            // 飞来峰 45 + 灵隐 30
      '西溪湿地':'mid',          // 80
      '六和塔':'low',            // 20
      '净慈寺':'low',            // 10
      '杭州大剧院':'low',        // 以演出票为主
      '杭州植物园':'low',        // 10
      '香积寺':'low',            // 20
      '三潭印月':'mid',          // 船票 + 门票约 55
      '吴山城隍阁':'low',        // 30
      '胡雪岩故居':'low',        // 20
      '万松书院':'low',          // 10
      '良渚古城遗址公园':'mid',  // 80
      '法喜寺':'low'             // 10
    },
    '广州': {
      '陈家祠':'low',            // 10
      '广州塔':'high',           // 150–228 分塔层
      '光孝寺':'low',            // 5
      '六榕寺':'low',            // 5
      '宝墨园':'mid',            // 54
      '广州动物园':'low',        // 20
      '广州大剧院':'low',        // 以演出票为主
      '白云山':'low',            // 5
      '华南国家植物园':'low',    // 20
      '中山纪念堂':'low',        // 10
      '广州博物馆':'low',        // 10
      '珠江夜游':'mid',          // 80–150
      '长隆野生动物世界':'high', // 350
      '长隆欢乐世界':'high',     // 250
      '岭南印象园':'mid',        // 60
      '城隍庙':'low'             // 10
    },
    '成都': {
      '成都武侯祠':'low',        // 50
      '杜甫草堂':'low',          // 50
      '成都大熊猫繁育研究基地':'mid', // 55
      '青羊宫':'low',            // 10
      '金沙遗址':'mid',          // 70
      '望江楼公园':'low',        // 20
      '都江堰':'mid',            // 80
      '青城山':'mid',            // 前山 90
      '天府熊猫塔':'mid'         // 80
    }
  };

  /* 住宿：每城按区域分档，价位是**标间/晚**的常见区间（非最低价）。
     区域名沿用各城市原有 stay 的叫法，便于与既有的住宿推荐衔接。 */
  const STAY = {
    '北京': [
      { area:'前门一带',   tier:'low',  range:'¥180–320', note:'老城胡同片区，去天安门、天坛都顺路' },
      { area:'南锣鼓巷周边', tier:'low', range:'¥200–350', note:'胡同客栈多，夜里安静' },
      { area:'王府井 / 东单', tier:'mid', range:'¥350–600', note:'地铁换乘方便，餐饮选择多' },
      { area:'三里屯',     tier:'high', range:'¥600–1000+', note:'夜生活与商圈，离主要古建较远' }
    ],
    '上海': [
      { area:'人民广场一带', tier:'mid',  range:'¥350–600', note:'地铁枢纽，博物馆与南京路步行可达' },
      { area:'静安寺 / 南京西路', tier:'mid', range:'¥400–700', note:'商业与梧桐街区交界' },
      { area:'中山公园 / 五角场', tier:'low', range:'¥200–380', note:'性价比高，通勤时间略长' },
      { area:'新天地 / 外滩', tier:'high', range:'¥700–1300+', note:'滨水与石库门，位置最好也最贵' }
    ],
    '威海': [
      { area:'威海站一带', tier:'low',  range:'¥150–280', note:'进出城方便，去各海湾都顺' },
      { area:'环翠楼 / 市中心', tier:'mid', range:'¥280–450', note:'老城生活区，餐饮集中' },
      { area:'国际海水浴场', tier:'mid', range:'¥300–500', note:'旺季看海，价格随季节浮动明显' }
    ],
    '杭州': [
      { area:'湖滨 / 南山路', tier:'mid',  range:'¥400–700', note:'紧邻西湖东线，出门即景区' },
      { area:'清河坊一带', tier:'low',  range:'¥220–380', note:'老街动线上，小吃与市集多' },
      { area:'西溪 / 龙井', tier:'high', range:'¥700–1200+', note:'度假型住宿，离市中心较远' }
    ],
    '广州': [
      { area:'北京路一带', tier:'low',  range:'¥200–350', note:'老城中心，西关人文动线起点' },
      { area:'天河 / 珠江新城', tier:'mid', range:'¥400–700', note:'新中轴，去广州塔与博物馆方便' },
      { area:'沙面 / 白鹅潭', tier:'mid', range:'¥350–600', note:'江畔洋楼片区，夜景好' }
    ],
    '成都': [
      { area:'玉林一带',   tier:'low',  range:'¥180–320', note:'夜间小馆聚集的生活街区' },
      { area:'春熙路一带', tier:'mid',  range:'¥350–600', note:'商圈中心，地铁方便' },
      { area:'太古里周边', tier:'high', range:'¥600–1000+', note:'核心商圈，价格最高' }
    ]
  };

  /** 某城某景点的门票档位。没登记的按免费处理。 */
  function tierOf(city, name){
    const t = (SPOT_TIER[city] || {})[name];
    return t || 'free';
  }

  const RANK = { free:0, low:1, mid:2, high:3 };

  /** 这个景点在给定预算下能不能去。budget 是**允许的最高档位**（low/mid/high）。 */
  function withinBudget(city, name, budget){
    if(!budget) return true;
    return RANK[tierOf(city, name)] <= RANK[budget];
  }

  /** 这趟排线有没有超出预算：只要有一天里出现一个超档位的点，就算超。
      住宿不参与这个判定——它走「按预算推荐」那条路（stayPicks），
      因为住宿是可换的，而景点是路线本身，超了就得重排。 */
  function overBudget(city, routeDays, budget){
    if(!budget) return false;
    return (routeDays || []).some(day => (day || []).some(n => !withinBudget(city, n, budget)));
  }

  /** 档位代表值，用于把「一天去了哪些点」折算成一个可加总的数。 */
  function priceOf(city, name){ return TIER[tierOf(city, name)].mid; }
  /** 一趟排线的门票人均合计（按档位中值估）。 */
  function ticketTotal(city, routeDays){
    return (routeDays || []).reduce((sum, day) =>
      sum + (day || []).reduce((s, n) => s + priceOf(city, n), 0), 0);
  }
  /** 某城住宿按预算档挑候选。tier 为 null 时返回全部。 */
  function stayPicks(city, tier){
    const list = STAY[city] || [];
    return tier ? list.filter(s => s.tier === tier) : list;
  }

  const API = { TIER, SPOT_TIER, STAY, RANK, tierOf, withinBudget, overBudget, priceOf, ticketTotal, stayPicks };
  if (typeof module === 'object' && module.exports) module.exports = API;
  globalThis.TOURIS_BUDGET = API;
})();
